import{_ as t,o as a,c as o,a5 as l}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Server Example: Fluid Pool","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/fluid_pool.md","filePath":"sections/examples/server/fluid_pool.md"}'),i={name:"sections/examples/server/fluid_pool.md"};function d(r,e,s,h,n,c){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="server-example-fluid-pool" tabindex="-1">Server Example: Fluid Pool <a class="header-anchor" href="#server-example-fluid-pool" aria-label="Permalink to &quot;Server Example: Fluid Pool&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Bodies of different densities fall into a pool 4 m by 2.4 m, filled with water to 0.7 m under air (<a href="./../../Fluids.html">Fluids</a>). The water holds each one up with the weight of the water it displaces, at the center of that volume.</p><ul><li>The ice block floats with 8 % of its height above the surface.</li><li>The half-dense wooden cube turns an edge up: a cube of density between 0.28 and 0.72 times that of water does not float on a face.</li><li>The raft and the log float flat.</li><li>The hollow ball rides high. It also feels the buoyancy of the air, 6 % of its weight.</li><li>The steel ball and the brick sink to the floor.</li></ul><p>The waves the bodies make as they bob carry their energy away, so they settle within a few periods. Every fifteen seconds the world starts over, and the example prints how each body came to rest:</p><table tabindex="0"><thead><tr><th>Body</th><th>Expected</th><th>Example</th></tr></thead><tbody><tr><td>Ice above the water</td><td>8.1 %</td><td>7.6 % (still settling)</td></tr><tr><td>Wooden cube tilt</td><td>45°</td><td>42 to 45°</td></tr><tr><td>Raft draft</td><td>4.0 cm</td><td>4.0 cm</td></tr><tr><td>Steel ball over the floor</td><td>6 cm</td><td>5.9 cm</td></tr></tbody></table><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>fluid_pool</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/fluid_pool</span></span></code></pre></div><p>Connect <code>rayrai_tcp_viewer</code> to port 8080. On Windows, run <code>build-examples/bin/fluid_pool.exe</code>.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>The pool is a <code>FluidVolume</code> bounded by its walls, from the floor up to its surface, and the air fills the rest of the world (<code>World::setAmbientFluid()</code>).</li><li>The TCP viewer draws the water of the pool: the server sends it the world&#39;s volumes of liquid.</li><li>The scene lives in <code>include/fluid_pool.hpp</code>.</li></ul>',13)])])}const f=t(i,[["render",d]]);export{u as __pageData,f as default};
